using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RaceDayAPI.Data;using RaceDayAPI.Models;using System.Security.Claims;namespace RaceDayAPI.Controllers{    [Route("api/[controller]")]    [ApiController]    public class ResultsController : ControllerBase    {        private readonly RaceDayDbContext _context;        public ResultsController(RaceDayDbContext context)        {            _context = context;        }        [HttpPost]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> CreateResult([FromBody] ResultDto dto)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var enrolment = await _context.Enrolments                .Include(e => e.Event)                .FirstOrDefaultAsync(e => e.EnrolmentID == dto.EnrolmentID);            if (enrolment == null) return NotFound("Enrolment not found.");            if (enrolment.Event.OrganiserID != organiser.OrganiserID) return Forbid();            if (await _context.Results.AnyAsync(r => r.EnrolmentID == dto.EnrolmentID))                return BadRequest("Result already captured for this enrolment.");            var result = new Result            {                EnrolmentID = dto.EnrolmentID,                FinishTime = dto.FinishTime,                OverallPosition = dto.OverallPosition,                CategoryPosition = dto.CategoryPosition,                IsDisqualified = dto.IsDisqualified,                Notes = dto.Notes            };            _context.Results.Add(result);            enrolment.Status = "Completed";            await _context.SaveChangesAsync();            return Ok(result);        }        [HttpGet("me")]        [Authorize(Roles = "Participant")]        public async Task<IActionResult> GetMyResults()        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var participant = await _context.Participants.FirstOrDefaultAsync(p => p.UserID == userId);            if (participant == null) return Forbid();            var results = await _context.Results                .Include(r => r.Enrolment).ThenInclude(e => e.Event)                .Include(r => r.Enrolment).ThenInclude(e => e.Category)                .Where(r => r.Enrolment.ParticipantID == participant.ParticipantID)                .ToListAsync();            return Ok(results);        }        [HttpGet("event/{eventId}")]        [Authorize(Roles = "Organiser")]        public async Task<IActionResult> GetResultsForEvent(int eventId)        {            var userId = int.Parse(User.FindFirst(ClaimTypes.NameIdentifier)!.Value);            var organiser = await _context.Organisers.FirstOrDefaultAsync(o => o.UserID == userId);            if (organiser == null) return Forbid();            var ev = await _context.Events.FirstOrDefaultAsync(e => e.EventID == eventId);            if (ev == null) return NotFound();            if (ev.OrganiserID != organiser.OrganiserID) return Forbid();            var results = await _context.Results                .Include(r => r.Enrolment).ThenInclude(e => e.Participant).ThenInclude(p => p.User)                .Where(r => r.Enrolment.EventID == eventId)                .OrderBy(r => r.OverallPosition)                .ToListAsync();            return Ok(results);        }    }    public class ResultDto    {        public int EnrolmentID { get; set; }        public TimeSpan FinishTime { get; set; }        public int? OverallPosition { get; set; }        public int? CategoryPosition { get; set; }        public bool IsDisqualified { get; set; }        public string? Notes { get; set; }    }}